arguments.command:
cd /workspace/submission/src/offline && python3 - <<'EOF'
p='ReceiveAudit.java'
s=open(p).read()
s=s.replace("import java.util.List;\nimport java.util.Map;","import java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;")
helper = '''
    private void addPacketRow(int event, int packet, int offset, String level, Long pn, Long epoch,
            String status, String hash) {
        packetRows.add(Main.object(
                "event", event,
                "packet", packet,
                "offset", offset,
                "level", level,
                "pn", pn,
                "epoch", epoch,
                "status", status,
                "sha256", hash));
    }

    private static String sha256(byte[] data) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return hex(digest.digest(data));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    // ------------------------------------------------------------------ result
'''
s=s.replace("    // ------------------------------------------------------------------ result\n", helper, 1)
open(p,'w').write(s)
EOF
cd /workspace && python3 build.py /workspace/submission/src /workspace/tmp/classes 2>&1 | head -30
